1	import { rulesPresets, type RulesPresetId } from "@pirate-sea-race/content";
2	import { describe, expect, it } from "vitest";
3	import { nextInt } from "../random.js";
4	import {
5	  activeDuelOf,
6	  activeTonic,
7	  addPlayer,
8	  advanceLedger,
9	  cacheRubbings,
10	  cancelChannel,
11	  checkLedger,
12	  chooseTheft,
13	  createLedger,
14	  disconnectPlayer,
15	  eligibleTheftTypes,
16	  expireReservation,
17	  findPlayer,
18	  findRubbing,
19	  grantGold,
20	  hashState,
21	  heldTypes,
22	  objectiveRules,
23	  progressChannel,
24	  purchase,
25	  quitPlayer,
26	  reconnectPlayer,
27	  reportDuelResult,
28	  reserveDuel,
29	  startCacheClaim,
30	  startCollect,
31	  unlockSource,
32	  useTonic,
33	  type LedgerState,
34	  type LedgerStep,
35	  type Transfer,
36	} from "./index.js";
37	
38	/** Freezes a state deeply, so any operation that writes into its input throws. */
39	function deepFreeze<T>(value: T): T {
40	  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
41	  for (const child of Object.values(value)) deepFreeze(child);
42	  return Object.freeze(value);
43	}
44	
45	/** The test's own seeded generator, apart from the ledger's. */
46	class Dice {
47	  constructor(private state: number) {}
48	  int(bound: number): number {
49	    const drawn = nextInt(this.state, bound);
50	    this.state = drawn.state;
51	    return drawn.value;
52	  }
53	  pick<T>(items: readonly T[]): T {
54	    return items[this.int(items.length)]!;
55	  }
56	  percent(chance: number): boolean {
57	    return this.int(1000) < chance * 10;
58	  }
59	}
60	
61	type Stats = Record<string, number>;
62	
63	interface Outcome {
64	  readonly ok: boolean;
65	  readonly rejection: string | null;
66	  readonly transfers?: readonly Transfer[];
67	  readonly status?: string | null;
68	  readonly cacheIds?: readonly string[];
69	  /** A purchase's kept refusal, and whether it was a replay of one kept earlier. */
70	  readonly refusal?: object | null;
71	  readonly replayed?: boolean;
72	}
73	
74	/**
75	 * A seeded random match: players join, collect, get interrupted, duel (won, lost, drawn, cancelled), choose or let
76	 * the window lapse, repeat old messages, disconnect, return, expire, quit and claim from caches, earn ruin and supply
77	 * gold, buy (and retry buying) rumors and tonics and use tonics, mixed with invalid, duplicate and stale requests.
78	 * After every operation the invariant holds, a rejected request returned its input state (a purchase refusal decided
79	 * for the first time only adds itself to the kept requests), every reported transfer matches where the rubbing now is,
80	 * gold is accounted for and never negative, and each player carries 0 to 2 tonics with at most one active.
81	 */
82	function simulate(preset: RulesPresetId, seed: number, steps: number, check = true): { state: LedgerState; stats: Stats } {
83	  const dice = new Dice(seed ^ 0x5eed);
84	  const { islands, sourcesPerIsland, maxPlayers } = rulesPresets[preset];
85	  const sites = Array.from({ length: islands * sourcesPerIsland }, (_, index) => ({
86	    island: Math.floor(index / sourcesPerIsland),
87	    x: dice.int(50_000),
88	    y: dice.int(50_000),
89	  }));
90	  // Purses differ between seeds through the rules, never per player.
91	  const rules = { ...objectiveRules, startingGold: [50, 20, 90][seed % 3]! };
92	  const supplyCaches = ["supply-0", "supply-1", "supply-2", "supply-3"];
93	  let state = deepFreeze(createLedger({ preset, seed, sites, rules, supplyCaches }));
94	  const stats: Stats = {};
95	  const count = (key: string) => (stats[key] = (stats[key] ?? 0) + 1);
96	  let now = 0;
97	  let joined = 0;
98	  let duelNumber = 0;
99	  const messages: (() => LedgerStep<Outcome>)[] = [];
100	  /** Request ids count per player, so different players use the same ids all the time. */
101	  const requestNumbers = new Map<string, number>();
102	  const decided: { requestId: string; playerId: string; item: "rumor" | "tonic" }[] = [];
103	
104	  const apply = <Q, R extends Outcome>(label: string, op: (s: LedgerState, q: Q) => LedgerStep<R>, request: Q): R => {
105	    const before = state;
106	    const { state: after, result } = op(before, request);
107	    count("operations");
108	    count(`${label}:${result.ok ? "ok" : result.rejection}`);
109	    if (result.status) count(`status:${result.status}`);
110	    if (!check) {
111	      state = after;
112	      return result;
113	    }
114	    const problems = checkLedger(after);
115	    if (problems.length > 0) throw new Error(`seed ${seed}, ${label} ${JSON.stringify(request)}:\n${problems.join("\n")}`);
116	    if (!result.ok && after !== before && !firstRefusal(before, after, result)) {
117	      throw new Error(`${label} was rejected (${result.rejection}) but changed the state`);
118	    }
119	    economyCheck(after, label);
120	    const moved = new Set<string>();
121	    for (const transfer of result.transfers ?? []) {
122	      if (moved.has(transfer.rubbingId)) throw new Error(`${label} moved ${transfer.rubbingId} twice`);
123	      moved.add(transfer.rubbingId);
124	      const rubbing = findRubbing(after, transfer.rubbingId)!;
125	      expect(rubbing.location).toEqual(transfer.to);
126	      expect(rubbing.revision).toBe(transfer.revisionAfter);
127	      expect(transfer.revisionAfter).toBe(transfer.revisionBefore + 1);
128	      expect(findRubbing(before, transfer.rubbingId)!.location).toEqual(transfer.from);
129	    }
130	    state = deepFreeze(after);
131	    return result;
132	  };
133	
134	  /**
135	   * A purchase refusal decided for the first time is kept: the only change is that refusal (and the clock), so it
136	   * charged nothing. Every other rejection must return its input state.
137	   */
138	  const firstRefusal = (before: LedgerState, after: LedgerState, result: Outcome): boolean => {
139	    if (!result.refusal || result.replayed !== false) return false;
140	    const unchanged = hashState({ ...after, requests: before.requests, tick: before.tick }) === hashState(before);
141	    if (!unchanged || after.requests.at(-1) !== result.refusal) throw new Error(`seed ${seed}: a kept refusal changed more than the requests`);
142	    return true;
143	  };
144	
145	  /** §11's economy after every step, stated directly rather than only through `checkLedger`. */
146	  const economyCheck = (after: LedgerState, label: string) => {
147	    let balances = 0;
148	    for (const player of after.players) {
149	      balances += player.gold;
150	      // One effect slot per player, so at most one tonic is active: the slot must be the one activation that fits.
151	      const effect = player.tonicEffect;
152	      const oneEffect = effect === null || effect.endTick - effect.startTick === after.rules.tonicTicks;
153	      if (player.gold < 0 || player.tonics < 0 || player.tonics > after.rules.tonicCarryLimit || !oneEffect) {
154	        throw new Error(`seed ${seed}, ${label}: player ${player.id} has ${player.gold} gold, ${player.tonics} tonics, ${JSON.stringify(effect)}`);
155	      }
156	    }
157	    if (balances + after.goldSpent !== after.goldIssued) throw new Error(`seed ${seed}, ${label}: gold is not accounted for`);
158	  };
159	
160	  const players = () => state.players.map((player) => player.id);
161	  const present = () => state.players.filter((player) => player.status !== "left").map((player) => player.id);
162	  /** Mostly a player still in the match; sometimes one who left, or an unknown id. */
163	  const anyPlayer = () => {
164	    const roll = dice.int(100);
165	    if (roll < 88 && present().length > 0) return dice.pick(present());
166	    if (roll < 97 && players().length > 0) return dice.pick(players());
167	    return "ghost";
168	  };
169	  const idle = () => present().filter((id) => activeDuelOf(state, id) === undefined);
170	  const position = () => ({ x: dice.int(50_000), y: dice.int(50_000) });
171	
172	  /** A run of world ticks: the clock advances and each channelling player holds on, now and then letting go a tick. */
173	  const ticks = () => {
174	    for (let burst = 1 + dice.int(20); burst > 0; burst--) {
175	      now += 1;
176	      // The room advances every tick; here only when a choice window is due, or at random, to keep the test quick.
177	      const due = state.duels.some((duel) => duel.phase === "choosing" && duel.choiceDeadline! <= now);
178	      if (due || dice.percent(10)) {
179	        const advanced = apply("advance", advanceLedger, { tick: now });
180	        for (const duel of advanced.settled) count(`default-theft:${duel.settlement!.stolenType === null ? "none" : "type"}`);
181	      }
182	      for (const player of state.players) {
183	        if (player.channel !== null && !dice.percent(0.3)) {
184	          const progress = apply("progress", progressChannel, { playerId: player.id, tick: now });
185	          if (progress.status === "claimed" || progress.status === "collected") {
186	            expect(findRubbing(state, progress.rubbingId!)!.location).toEqual({ kind: "player", playerId: player.id });
187	          }
188	        }
189	      }
190	    }
191	  };
192	
193	  const actions: [number, () => void][] = [
194	    [40, ticks],
195	    [1, () => {
196	      now += 1 + dice.int(1500);
197	      apply("advance", advanceLedger, { tick: now });
198	    }],
199	    [3, () => {
200	      const fresh = present().length < maxPlayers && dice.percent(90);
201	      const playerId = fresh ? `p${++joined}` : anyPlayer();
202	      // Joins once drew a random purse here. Purses now come from the rules alone, but the draw stays so the seeded
203	      // match sequence is the one it always was.
204	      if (dice.percent(20)) dice.int(400);
205	      apply("join", addPlayer, { playerId, tick: now });
206	    }],
207	    [4, () => {
208	      const playerId = anyPlayer();
209	      const held = new Set(findPlayer(state, playerId) ? heldTypes(state, playerId) : []);
210	      const sealed = state.sources.filter((source) => findRubbing(state, source.rubbingId)!.location.kind === "source");
211	      const useful = sealed.filter((source) => !held.has(source.type));
212	      const already = sealed.filter((source) => held.has(source.type));
213	      const roll = dice.int(100);
214	      const source =
215	        roll < 65 && useful.length > 0 ? dice.pick(useful) : roll < 80 && already.length > 0 ? dice.pick(already) : dice.pick(state.sources);
216	      apply("start-collect", startCollect, { playerId, sourceId: dice.percent(97) ? source.id : "source-99-9", tick: now });
217	    }],
218	    [4, () => {
219	      const playerId = anyPlayer();
220	      if (state.caches.length === 0) return;
221	      const cache = dice.pick(state.caches);
222	      const held = new Set(findPlayer(state, playerId) ? heldTypes(state, playerId) : []);
223	      const inside = cacheRubbings(state, cache.id);
224	      const wanted = inside.filter((rubbing) => !held.has(rubbing.type));
225	      const rubbing = dice.percent(80) && wanted.length > 0 ? dice.pick(wanted) : dice.pick(state.rubbings);
226	      apply("start-claim", startCacheClaim, { playerId, cacheId: cache.id, rubbingId: rubbing.id, tick: now });
227	    }],
228	    [1, () => apply("cancel", cancelChannel, { playerId: anyPlayer(), tick: now })],
229	    [2, () => {
230	      // A rival starts on the same rubbing someone is already channelling: only one of them may get it.
231	      const channelling = state.players.filter((player) => player.channel !== null);
232	      const rivals = idle().filter((id) => findPlayer(state, id)!.status === "connected" && findPlayer(state, id)!.channel === null);
233	      if (channelling.length === 0 || rivals.length === 0) return;
234	      const channel = dice.pick(channelling).channel!;
235	      const playerId = dice.pick(rivals);
236	      if (channel.kind === "collect") apply("contest-collect", startCollect, { playerId, sourceId: channel.sourceId, tick: now });
237	      else apply("contest-claim", startCacheClaim, { playerId, cacheId: channel.cacheId, rubbingId: channel.rubbingId, tick: now });
238	    }],
239	    [4, () => {
240	      if (players().length < 2) return;
241	      const reuse = dice.percent(5) && duelNumber > 0;
242	      const duelId = reuse ? `d${1 + dice.int(duelNumber)}` : `d${++duelNumber}`;
243	      const free = idle();
244	      const pair = free.length >= 2 && dice.percent(85) ? [dice.pick(free), dice.pick(free)] : [anyPlayer(), anyPlayer()];
245	      const request = { duelId, players: [pair[0]!, pair[1]!] as const, tick: now };
246	      apply("reserve", reserveDuel, request);
247	      messages.push(() => reserveDuel(state, { ...request, tick: now }));
248	    }],
249	    [4, () => {
250	      const open = state.duels.filter((duel) => duel.phase === "fighting");
251	      const duel = dice.percent(90) && open.length > 0 ? dice.pick(open) : state.duels.length > 0 ? dice.pick(state.duels) : undefined;
252	      if (!duel) return;
253	      const roll = dice.int(100);
254	      const request =
255	        roll < 75
256	          ? { duelId: duel.id, tick: now, outcome: "win" as const, winner: dice.percent(95) ? dice.pick(duel.players) : anyPlayer() }
257	          : roll < 95
258	            ? { duelId: duel.id, tick: now, outcome: "draw" as const }
259	            : { duelId: duel.id, tick: now, outcome: "cancelled" as const };
260	      const result = apply("result", reportDuelResult, request);
261	      if (result.ok && result.duel!.phase === "settled" && request.outcome === "win") count("settled-without-choice");
262	      messages.push(() => reportDuelResult(state, { ...request, tick: now }));
263	    }],
264	    [4, () => {
265	      const choosing = state.duels.filter((duel) => duel.phase === "choosing");
266	      if (choosing.length === 0) return;
267	      const duel = dice.pick(choosing);
268	      const eligible = eligibleTheftTypes(state, duel.id);
269	      const type = dice.percent(80) && eligible.length > 0 ? dice.pick(eligible) : dice.pick(state.types);
270	      const playerId = dice.percent(80) ? duel.result!.winner! : dice.pick(duel.players);
271	      const request = { duelId: duel.id, playerId, type, tick: now };
272	      const result = apply("choose", chooseTheft, request);
273	      if (result.ok) count(`chosen-theft:${result.duel!.settlement!.stolenType === null ? "none" : "type"}`);
274	      messages.push(() => chooseTheft(state, { ...request, tick: now }));
275	    }],
276	    [3, () => {
277	      if (messages.length === 0) return;
278	      const replay = dice.pick(messages);
279	      const before = state;
280	      const { state: after, result } = replay();
281	      count("operations");
282	      count(`repeat:${result.ok ? "ok" : result.rejection}`);
283	      if (check) {
284	        expect(checkLedger(after)).toEqual([]);
285	        if (!result.ok) expect(after).toBe(before);
286	      }
287	      state = check ? deepFreeze(after) : after;
288	    }],
289	    [2, () => apply("disconnect", disconnectPlayer, { playerId: anyPlayer(), tick: now })],
290	    [2, () => apply("reconnect", reconnectPlayer, { playerId: anyPlayer(), tick: now })],
291	    [2, () => {
292	      const waiting = state.players.filter((player) => player.status === "disconnected");
293	      const target = waiting.length > 0 && dice.percent(80) ? dice.pick(waiting) : undefined;
294	      if (target && dice.percent(60)) now = Math.max(now, target.reservationDeadline!);
295	      const result = apply("expire", expireReservation, { playerId: target?.id ?? anyPlayer(), tick: now, position: position() });
296	      if (result.ok && result.duel) count("expire-in-duel");
297	    }],
298	    [1, () => {
299	      const result = apply("quit", quitPlayer, { playerId: anyPlayer(), tick: now, position: position() });
300	      if (result.ok && result.duel) count(`quit-in-duel:${result.duel.phase}`);
301	    }],
302	    [2, () => apply("unlock", unlockSource, { sourceId: dice.pick(state.sources).id, tick: now })],
303	    [1, () => {
304	      if (state.tick === 0) return;
305	      const stale = state.tick - 1 - dice.int(Math.min(state.tick, 20));
306	      const result = apply("stale", addPlayer, { playerId: `late${stale}`, tick: stale });
307	      expect(result.rejection).toBe("stale-tick");
308	    }],
309	  ];
310	  const total = actions.reduce((sum, [weight]) => sum + weight, 0);
311	
312	  /**
313	   * §11's economy draws from its own dice between the steps above. Gold and tonics never steer those steps' draws,
314	   * so the match around the economy is the same sequence it was before the economy existed.
315	   */
316	  const shop = new Dice(seed ^ 0xc01d);
317	  const shopper = () => {
318	    const roll = shop.int(100);
319	    if (roll < 88 && present().length > 0) return shop.pick(present());
320	    if (roll < 97 && players().length > 0) return shop.pick(players());
321	    return "ghost";
322	  };
323	  const economy: [number, () => void][] = [
324	    [4, () => {
325	      // Ruins are keyed per player, supply caches once per match; a small pool of keys makes repeats common. One key
326	      // in each pool is unknown to the ledger (an island past the last, a supply cache it was not given).
327	      const reason = shop.percent(50) ? ("ruin" as const) : ("supply-cache" as const);
328	      const sourceKey = reason === "ruin" ? String(shop.int(islands + 1)) : `supply-${shop.int(supplyCaches.length + 1)}`;
329	      apply(`grant-${reason}`, grantGold, { playerId: shopper(), reason, sourceKey, tick: now });
330	    }],
331	    [4, () => {
332	      const roll = shop.int(100);
333	      if (roll < 25 && decided.length > 0) {
334	        // A retry of an earlier decision, purchase or refusal: the original result, no charge, the same state. Now
335	        // and then the player reuses their own id for the other item, which is a duplicate.
336	        const earlier = shop.pick(decided);
337	        const request = shop.percent(85) ? earlier : { ...earlier, item: earlier.item === "rumor" ? ("tonic" as const) : ("rumor" as const) };
338	        const before = state;
339	        const original = before.requests.find((outcome) => outcome.playerId === earlier.playerId && outcome.requestId === earlier.requestId);
340	        const result = apply("rebuy", purchase, { ...request, tick: shop.percent(50) ? now : 0 });
341	        if (result.replayed) {
342	          count(result.ok ? "purchase-replayed" : "refusal-replayed");
343	          expect(state).toBe(before);
344	          expect(result.purchase ?? result.refusal).toBe(original);
345	        } else if (original === undefined) {
346	          count("evicted-refusal-decided-again");
347	        }
348	        return;
349	      }
350	      const item = shop.pick(["rumor", "tonic"] as const);
351	      // Tonic buyers are often players who carry one already, so the carry limit is reached.
352	      const carrying = state.players.filter((player) => player.tonics > 0).map((player) => player.id);
353	      const playerId = item === "tonic" && carrying.length > 0 && shop.percent(50) ? shop.pick(carrying) : shopper();
354	      const number = (requestNumbers.get(playerId) ?? 0) + 1;
355	      requestNumbers.set(playerId, number);
356	      const request = { requestId: `r${number}`, playerId, item };
357	      if (state.requests.some((outcome) => outcome.requestId === request.requestId && outcome.playerId !== playerId)) count("request-id-shared");
358	      const result = apply(`buy-${item}`, purchase, { ...request, tick: now });
359	      if (result.ok || result.refusal) decided.push(request);
360	    }],
361	    [3, () => {
362	      const atSea = shop.percent(85);
363	      const grappled = shop.percent(10);
364	      // Often a player whose tonic is still active, who must not start a second one.
365	      const sailing = state.players.filter((player) => activeTonic(state, player.id, now)).map((player) => player.id);
366	      const playerId = sailing.length > 0 && shop.percent(40) ? shop.pick(sailing) : shopper();
367	      const wasActive = activeTonic(state, playerId, now);
368	      const result = apply("use-tonic", useTonic, { playerId, tick: now, atSea, grappled });
369	      // Tonics never stack: an activation only ever succeeds when none was active for that player just before.
370	      if (result.ok && wasActive) throw new Error(`seed ${seed}: player ${playerId} stacked a second tonic at ${now}`);
371	      if (result.ok && activeTonic(state, playerId, now) && !activeTonic(state, playerId, now + state.rules.tonicTicks)) count("tonic-active");
372	    }],
373	  ];
374	  const economyTotal = economy.reduce((sum, [weight]) => sum + weight, 0);
375	
376	  for (let step = 0; step < steps; step++) {
377	    let roll = dice.int(total);
378	    const action = actions.find(([weight]) => (roll -= weight) < 0)!;
379	    action[1]();
380	    if (shop.percent(40)) {
381	      let pick = shop.int(economyTotal);
382	      economy.find(([weight]) => (pick -= weight) < 0)![1]();
383	    }
384	  }
385	  for (const duel of state.duels) {
386	    if (duel.settlement?.goldSuppressed) count("gold-suppressed");
387	    if (duel.result?.forfeit) count("forfeit");
388	    if (duel.settlement?.stolenRubbingId !== null && duel.settlement?.stolenRubbingId !== undefined) count("theft");
389	    if (duel.result?.outcome === "win" && duel.settlement?.stolenRubbingId === null) count("win-without-theft");
390	  }
391	  stats.caches = state.nextCacheNumber - 1;
392	  stats.rumors = state.players.filter((player) => player.freshRumors.length > 0).length;
393	  return { state, stats };
394	}
395	
396	const SEEDS = [1, 2, 3];
397	const STEPS = 1200;
398	
399	/** Each rule the sequences exercise, by the stats that show it happened (any of them). */
400	const EXERCISED: [string, string[]][] = [
401	  ["collection", ["status:collected"]],
402	  ["cache claim", ["status:claimed"]],
403	  ["contested completion fails", ["status:failed"]],
404	  ["interrupted hold resets", ["status:reset"]],
405	  ["cancelled hold", ["status:cancelled"]],
406	  ["held type refused", ["start-collect:type-held", "start-claim:type-held", "contest-collect:type-held", "contest-claim:type-held"]],
407	  ["winner's theft choice", ["chosen-theft:type"]],
408	  ["default theft at the deadline", ["default-theft:type"]],
409	  ["win with no eligible type", ["settled-without-choice"]],
410	  ["refused choice", ["choose:ineligible-type", "choose:not-winner", "choose:choice-window-closed"]],
411	  ["draw or win recorded", ["result:ok"]],
412	  ["repeated result", ["result:already-resolved", "repeat:already-resolved"]],
413	  ["repeated reservation", ["repeat:duplicate", "reserve:duplicate"]],
414	  ["busy player", ["reserve:player-in-duel"]],
415	  ["theft", ["theft"]],
416	  ["gold without theft", ["win-without-theft"]],
417	  ["suppressed gold", ["gold-suppressed"]],
418	  ["forfeit on leaving a fight", ["forfeit"]],
419	  ["disconnect and return", ["reconnect:ok"]],
420	  ["late return", ["reconnect:reservation-expired"]],
421	  ["reservation expiry", ["expire:ok"]],
422	  ["early expiry refused", ["expire:reservation-active"]],
423	  ["quit", ["quit:ok"]],
424	  ["leaving during a choice window", ["quit-in-duel:choosing", "expire-in-duel"]],
425	  ["recovery caches", ["caches"]],
426	  ["fresh-rumor entitlements", ["rumors"]],
427	  ["stale requests", ["stale:stale-tick"]],
428	  ["ruin gold", ["grant-ruin:ok"]],
429	  ["repeated ruin grant", ["grant-ruin:duplicate"]],
430	  ["supply cache gold", ["grant-supply-cache:ok"]],
431	  ["supply cache claimed by another", ["grant-supply-cache:already-claimed"]],
432	  ["repeated supply cache grant", ["grant-supply-cache:duplicate"]],
433	  ["grant to a player who left", ["grant-ruin:player-left", "grant-supply-cache:player-left"]],
434	  ["rumor bought", ["buy-rumor:ok"]],
435	  ["tonic bought", ["buy-tonic:ok"]],
436	  ["repeated request id replayed", ["purchase-replayed"]],
437	  ["request id reused for another item", ["rebuy:duplicate"]],
438	  ["same request id from different players", ["request-id-shared"]],
439	  ["decided refusal replayed", ["refusal-replayed"]],
440	  ["grant for an unknown key", ["grant-ruin:unknown-source"]],
441	  ["supply cache the ledger was not given", ["grant-supply-cache:unknown-source"]],
442	  ["short gold", ["buy-rumor:insufficient-gold", "buy-tonic:insufficient-gold"]],
443	  ["third tonic", ["buy-tonic:tonic-limit"]],
444	  ["purchase in a duel", ["buy-rumor:player-in-duel", "buy-tonic:player-in-duel"]],
445	  ["purchase while disconnected", ["buy-rumor:player-disconnected", "buy-tonic:player-disconnected"]],
446	  ["purchase after leaving", ["buy-rumor:player-left", "buy-tonic:player-left"]],
447	  ["tonic used", ["use-tonic:ok"]],
448	  ["tonic active for its duration", ["tonic-active"]],
449	  ["second tonic while active", ["use-tonic:tonic-active"]],
450	  ["no tonic carried", ["use-tonic:no-tonic"]],
451	  ["tonic off the sea", ["use-tonic:not-at-sea"]],
452	  ["tonic while grappled", ["use-tonic:grappled"]],
453	  ["tonic in a duel", ["use-tonic:player-in-duel"]],
454	  ["tonic after leaving", ["use-tonic:player-left"]],
455	];
456	
457	describe("ledger property: no rubbing is ever lost or duplicated (§19)", () => {
458	  for (const preset of ["slice", "alpha"] as const) {
459	    it(`keeps the invariant after every step of ${SEEDS.length} random ${preset} matches and replays them identically`, { timeout: 120_000 }, () => {
460	      const totals: Stats = {};
461	      for (const seed of SEEDS) {
462	        const first = simulate(preset, seed, STEPS);
463	        // The replay skips the per-step checks, which draw nothing from the dice, so it is the same sequence.
464	        const again = simulate(preset, seed, STEPS, false);
465	        expect(hashState(again.state)).toBe(hashState(first.state));
466	        expect(again.stats).toEqual(first.stats);
467	        expect(first.stats.operations).toBeGreaterThan(2000);
468	        for (const [key, value] of Object.entries(first.stats)) totals[key] = (totals[key] ?? 0) + value;
469	      }
470	      // The invariant was not checked vacuously: every rule the sequences are meant to exercise happened.
471	      const missing = EXERCISED.filter(([, keys]) => keys.every((key) => (totals[key] ?? 0) === 0)).map(([rule]) => rule);
472	      expect(missing).toEqual([]);
473	    });
474	  }
475	
476	  it("replays to a different state from a different seed", { timeout: 60_000 }, () => {
477	    expect(hashState(simulate("alpha", 7, 1000, false).state)).not.toBe(hashState(simulate("alpha", 8, 1000, false).state));
478	  });
479	});
